mapper.select:
SELECT c.id, c.customer_no, c.customer_type, c.customer_name, c.industry, c.company_size, c.province, c.city, c.address, c.website, c.gender, c.birthday, c.occupation, c.phone, c.email, c.source, c.level, c.status, c.pool_type, c.owner_id, c.dept_id, c.lock_time, c.next_follow_time, c.remark, c.create_time, c.update_time, u.user_name as owner_name, d.dept_name FROM crm_customer c LEFT JOIN sys_user u ON c.owner_id = u.id LEFT JOIN sys_dept d ON c.dept_id = d.id WHERE c.pool_type = 1
AND c.customer_name LIKE CONCAT('%', #{query.customerName}, '%')
AND c.customer_type = #{query.customerType}
AND c.level = #{query.level}
AND c.status = #{query.status}
AND c.industry LIKE CONCAT('%', #{query.industry}, '%')
AND c.province LIKE CONCAT('%', #{query.province}, '%')
AND c.source LIKE CONCAT('%', #{query.source}, '%')
AND c.owner_id = #{query.ownerId}
ORDER BY c.create_time DESC
